ADMIN_ADDITION = '{/* PHASE6_ADMIN_GIFTS_DISPLAY */}\n                <div className="mt-4">\n                  <CharacterGiftsDisplay\n                    characterId={id}\n                    compact\n                  />\n                </div>'

for rel, content in NEW_FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print("Created:", rel)

by_file = {}
for rel, old, new in OPS:
    by_file.setdefault(rel, []).append((old, new))

for rel, replacements in by_file.items():
    path = ROOT / rel
    if not path.exists():
        raise SystemExit(f"ERROR: Missing {rel}")

    text = path.read_text(encoding="utf-8")

    for old, new in replacements:
        if old not in text:
            raise SystemExit(
                f"ERROR: Expected Phase 6 block not found in {rel}. "
                "Do not manually edit around it; send me the file if this happens."
            )
        text = text.replace(old, new, 1)

    path.write_text(text, encoding="utf-8")
    print("Updated:", rel)

# Admin character page is patched semantically because Phase 3 may not
# yet be present on the pushed GitHub copy, while it is present locally.
admin_rel = "app/(portal)/admin/characters/[id]/page.tsx"
admin_path = ROOT / admin_rel

if admin_path.exists():
    text = admin_path.read_text(encoding="utf-8")

    gift_import = (
        'import { CharacterGiftsDisplay } '
        'from "@/components/characters/character-gifts-display";\n'
    )

    if "@/components/characters/character-gifts-display" not in text:
        first_import = re.search(r'^import[^\n]+;\n', text, re.MULTILINE)
        if first_import:
            text = (
                text[:first_import.end()]
                + gift_import
                + text[first_import.end():]
            )

    if (
        "<AdminAncestryGiftSelector" in text
        and "PHASE6_ADMIN_GIFTS_DISPLAY" not in text
    ):
        match = re.search(
            r'(<AdminAncestryGiftSelector[\s\S]*?\n\s*/>)',
            text,
        )

        if match:
            replacement = (
                match.group(1)
                + "\n\n                "
                + ADMIN_ADDITION
            )
            text = (
                text[:match.start()]
                + replacement
                + text[match.end():]
            )
            print("Updated:", admin_rel)
        else:
            print(
                "WARNING: Admin Ancestry Gift selector exists but could not be safely patched."
            )
    else:
        print(
            "INFO: Admin Gift readout already present or Phase 3 selector not found."
        )

    admin_path.write_text(text, encoding="utf-8")

print()
print("SUCCESS")
print("Gifts Phase 6 installed.")
print("No SQL is required.")
print("Now run: npm run build")
